function circuit(canvas,on,swapped=false){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.textAlign='center';for(let j=0;j<2;j++){const x=20+(swapped?1-j:j)*380;c.font='16px sans-serif';c.fillStyle='#f0e7cf';c.fillText(j?'전지 두 개 직렬, 같은 3 V 전구':'전지 한 개, 같은 3 V 전구',x+170,25);
c.strokeStyle='#83b3c5';c.lineWidth=4;c.beginPath();c.moveTo(x+170,155);c.lineTo(x+170,180);c.lineTo(x+312,180);c.lineTo(x+312,214);c.stroke();c.beginPath();c.moveTo(x+158,132);c.lineTo(x+35,132);c.lineTo(x+35,245);c.lineTo(x+105,245);c.stroke();
paint(c,'bulb',on?(j?'bright':'dim'):'off',x+134,68,1.5);
for(let n=0;n<=j;n++)paint(c,'battery','default',x+100+n*80,228,1);
c.beginPath();c.moveTo(x+161,245);c.lineTo(x+(j?184:267),245);if(j){c.moveTo(x+241,245);c.lineTo(x+267,245)}c.lineTo(x+267,214);c.stroke();paint(c,'switch',on?'closed':'open',x+257,191);
c.fillStyle='#f0e7cf';c.font='13px sans-serif';c.fillText(on?'불빛을 비교해 보세요':swapped?'어느 쪽이 더 밝을지 골라 봐요':'스위치를 눌러 보세요',x+170,287)}}

function animateCircuit(canvas,on){let raf,alive=true;const start=performance.now(),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;function frame(now){if(!alive)return;const c=canvas.getContext('2d');c.clearRect(0,0,760,300);circuit(canvas,on);if(on){const t=reduce?1:Math.min(1,(now-start)/650);light(c,190,100,65,t*.55);light(c,570,100,115,t);if(!reduce){c.fillStyle='#ffe5a2';for(let i=0;i<9;i++){const x=534+(i*23)%80,y=130-((now/40+i*17)%95);c.globalAlpha=.22;c.fillRect(x,y,2,2)}c.globalAlpha=1}}raf=requestAnimationFrame(frame)}raf=requestAnimationFrame(frame);return()=>{alive=false;cancelAnimationFrame(raf)}}

