const MISSION_FULL={};
async function loadMissionDetails(){if(Object.keys(MISSION_FULL).length)return;try{const {missions}=await api('missions');await Promise.all(missions.map(async m=>{MISSION_FULL[m.id]=await api('mission?id='+encodeURIComponent(m.id))}))}catch{}}
function missionTask(e){const m=MISSION_FULL[e.payload.gameId],tid=String(e.payload.taskId||'').split('.').pop();return [m,m?.tasks.find(t=>t.id===tid)]}
function eventName(e){if(e.task==='writeup')return (e.payload.missionTitle||'의뢰')+': '+(e.payload.taskTitle||'설명 쓰기')+` (${e.payload.version||1}번째`+(e.payload.mode==='oral_teacher'?', 말로 설명하기':'')+')';if(e.task==='healthInquiry')return e.payload.taskTitle||'기후와 감염병 공동탐구';if(e.task==='discovery')return (e.payload.missionTitle||'탐구')+': '+({predicted:'처음 예상',trial:'조건 바꾸며 관찰',support:'도움 선택',reflection:'생각 돌아보기',transfer:'새 상황에 적용'})[e.payload.phase];if(!e.kind.startsWith('mission.'))return names[e.kind]||e.kind;if(['mission.predicted','mission.reflected','mission.transfer'].includes(e.kind))return (e.payload.missionTitle||'의뢰')+': '+(e.payload.taskTitle||'');const [m,t]=missionTask(e);if(!m)return '미션 기록';if(e.kind==='mission.completed')return m.place+': 의뢰 마무리 질문';return m.place+': '+(m.tasks.indexOf(t)+1)+'단계 '+(t?.title||'')+(e.kind==='mission.hint'?' (도움 열람)':'')}
function missionAnswer(e){const [m,t]=missionTask(e),p=e.payload,a=p.answer||'',r=p.roles||{},lab=(list,id)=>list?.find(o=>o.id===id)?.label||id||'';if(e.kind==='mission.hint')return '도움 '+p.hint+'단계';if(e.kind==='mission.completed'||!t)return a;
if(t.type==='choice')return lab(t.options,a);if(t.type==='multi')return a.split(',').map(x=>lab(t.options,x)).join(', ');if(t.type==='quiz')return t.parts.map(q=>q.prompt+' → '+lab(q.options,r[q.id])).join(' / ');if(t.type==='sort')return t.bins.map(b=>b.label+': '+t.items.filter(i=>r[i.id]===b.id).map(i=>i.label).join(', ')).join(' / ');if(t.type==='order')return a.split(',').map(x=>lab(t.cards,x)).join(' → ');if(t.type==='fill')return t.blanks.map(b=>lab(b.options,r[b.id])).join(' / ');if(t.type==='find')return a.split(',').map(x=>lab(t.spots,x)).join(', ');if(t.type==='action')return ({lit:'처음 조립에서 불이 켜짐','lit-after-flip':'동전 전지를 뒤집은 뒤 불이 켜짐',played:'기억 놀이를 끝까지 함',saved:'네 날의 태양길을 저장함',measured:'열두 달을 모두 기록함',compared:'여러 경우를 비교함',plotted:'그래프 점 12개를 찍음',made:'가려진 날 카드를 만들어 먼저 풀어 봄',recorded:'기록을 모두 마침',fast:'수레가 가장 빠른 판 각도를 찾음',waited:'판지를 5분 동안 햇빛에 둠',orbited:'시계 반대 방향으로 한 바퀴 공전시킴',explored:'자전축 기울기를 여러 개 살펴봄'})[a]||a;if(t.type==='number')return t.fields?t.fields.map(f=>f.prompt+' '+(r[f.id]??'')+(f.unit||'')).join(' / '):a+(t.unit||'');
if(t.type==='plan')return '장소 '+lab(t.places,r.place)+' / 기간 '+lab(t.periods,r.period)+' / 규칙 '+String(r.rules||'').split(',').map(x=>lab(t.rules,x)).join(', ')+(r.custom?' / 내가 만든 규칙: '+r.custom:'');if(t.type==='form')return t.fields.filter(f=>r[f.id]).map(f=>f.label+': '+(f.kind==='select'?lab(f.options,r[f.id]):r[f.id])).join(' / ');if(t.type==='grid')return t.rows.map(row=>row.label+': '+String(r[row.id]||'').split(',').map(x=>lab(t.cols,x)).join(', ')).join(' / ');if(t.type==='report'){const d=m.dex?.[r.product];return (d?.label||r.product)+' / '+lab(t.props,r.prop)+' / 출처 '+r.source+' / 편리한 점: '+a+(r.ask?' / 묻고 싶은 점: '+r.ask:'')}if(t.type==='signal'){const table=Object.entries(r).filter(([k])=>k.startsWith('p:')).map(([k,v])=>patternLabel(k.slice(2))+'='+v).join(', ');return r.sent!==undefined?'약속표('+table+') / 보낸 모양 '+patternLabel(r.sent)+' → "'+r.meaning+'"':'받은 모양 '+patternLabel(r.got||'')+' → 푼 뜻 "'+r.decoded+'"'}return a}
function eventAnswer(e){if(e.payload.responseText)return e.payload.responseText;if(e.kind.startsWith('pace.'))return (e.kind==='pace.entered'?(MISSION_FULL[e.payload.gameId]?.title||e.payload.gameId)+': ':'')+({story:'이야기 모두 보기',quick:'빠르게 문제만'}[e.payload.answer]||'');if(e.kind.startsWith('mission.'))return missionAnswer(e);if(e.kind==='duel.answered')return `${e.payload.region} ${e.payload.claim}: ${e.payload.label||''} (${e.payload.correct?'맞음':'다시 고름'})`;if(e.kind==='duel.completed')return e.payload.region+' 지구 단말 복구';const answer=e.payload.answer;if(e.kind.startsWith('crane.'))return (e.kind==='crane.poles'?(e.payload.battery==='reverse'?'방향 바꾼 뒤 ':'처음 ')+'오른쪽 끝 '+answer+'극':e.kind==='crane.counted'?'전지 '+(answer==='2'?'두 개 직렬':'한 개')+'로 세어 봄':e.kind==='crane.moved'?({attach:'붙이기',release:'화물통에 놓기',reject:'붙지 않는 금속 확인',heavy:'무거워서 떨어짐',battery:'전지 수 바꾸기'})[answer]+' / '+(e.payload.card||''):({on:'스위치 닫음',off:'스위치 열음',decrease:'붙는 정도가 크게 줄어듦',always:'늘 같다는 주장',zero:'반드시 하나도 남지 않는다는 주장',help:'도움 요청',recall:'처음 생각 기록',two:'두 개 직렬에서 더 많이 붙음',same:'같다는 주장',one:'한 개에서 더 많이 붙는다는 주장',south:'S극이 끌려옴',north:'N극이 끌려온다는 예상',pole:'극이 바뀜',strength:'세기가 세졌다는 주장',none:'변화 없다는 주장','false':'척척 알림이 틀렸다고 판단','true':'척척 알림이 맞다고 판단',done:'철 화물 세 개 운반',submit:'증거 정리 제출'})[answer])||answer;if(e.kind.startsWith('magnetIntro.'))return ({same:'전기가 통하면 모두 자석에 붙는다는 생각',different:'전도와 자석에 붙는 성질 구별',unknown:'아직 모름',battery:'전지',contact:'집게 접점',ends:'선 끝 피복',help:'도입 도움 요청'})[answer];if(e.kind.startsWith('magnetMaterials.'))return e.payload.roles?({iron:'철 볼트',brass:'황동 볼트',plastic:'플라스틱 볼트'})[answer]+' / '+Object.entries(e.payload.roles).map(([k,v])=>({bolt:'볼트',wire:'에나멜선',battery:'전지',switch:'스위치'})[k]+': '+({core:'철심',coil:'감긴 전류의 길',source:'전원',control:'연결과 끊기'})[v]).join(', '):'재료 도움 요청';if(e.kind.startsWith('magnetMeaning.'))return e.payload.roles?({electromagnet:'전류가 흐를 때 자석 성질',always:'감겨 있으면 언제나 자석',conductor:'모든 도체가 자석'})[e.payload.roles.name]+' / '+({heat:'전지와 전선 가열 주의',strong:'계속 세진다는 주장',empty:'철이 없어진다는 주장'})[e.payload.roles.reason]:'설명 도움 요청';if(e.kind.startsWith('magnetRepair.'))return ({battery:'전지',contact:'집게 접점',ends:'양 끝 피복',on:'잠깐 켜서 붙는지 재확인',help:'점검 도움 요청'})[answer];if(e.kind.startsWith('magnet.'))return ({current:'전류 유무에 따라 붙는 정도 변화',always:'감겨 있으면 언제나 붙는다는 주장',on:'스위치 닫음',off:'스위치 열음',help:'도움 요청'})[answer]||(e.payload.assembly?'감기 '+e.payload.assembly.turns+'단계 / 끝 처리 '+({ends:'양 끝만 벗김',all:'모두 벗김',covered:'피복 유지'})[e.payload.assembly.ends]:'안전 준비 확인');if(e.kind==='inquiry.features')return '손선풍기: '+({speed:'회전 빠르기',volume:'소리 크기',brightness:'전구 밝기'})[e.payload.roles.motor]+' / 알림 장치: '+({speed:'회전 빠르기',volume:'소리 크기',brightness:'전구 밝기'})[e.payload.roles.buzzer];if(e.kind==='inquiry.reviewed')return answer==='two'?'A는 전지 두 개 직렬':'A는 전지 한 개';if(e.kind.startsWith('application.'))return (e.payload.caseId==='car'?'자동차: ':'도서관 알림: ')+({one:'전지 한 개',two:'전지 두 개 직렬',help:'도움 요청'})[answer];if(e.kind.startsWith('motor.'))return({two:'두 개 직렬 쪽이 더 빠름',same:'같음 / 같은 규격',different:'다른 규격',on:'스위치 닫음',off:'스위치 열음',help:'도움 요청'})[answer];if(e.kind.startsWith('buzzer.'))return({two:'두 개 직렬 쪽의 소리가 더 큼',same:'소리 크기가 같음',plus:'빨간 선을 +극에 연결',minus:'빨간 선을 −극에 연결',on:'스위치 닫음',off:'스위치 열음',help:'도움 요청'})[answer];if(e.kind.startsWith('deduction.'))return({two:'전지 두 개 직렬로 추리',one:'전지 한 개로 추리',unknown:'조건 부족으로 판단 보류',light:'밝기 조사',motor:'회전 조사',sound:'소리 조사',help:'도움 요청'})[answer];return words[answer]}
