async function dashboard(){stopWorld();view='teacher';try{const data=await api('dashboard?student='+encodeURIComponent(selected));if(!data.students.some(s=>s.id===selected)&&data.students.length){selected=data.students[0].id;return dashboard()}await loadMissionDetails();if(view!=='teacher')return;sync.textContent='서버 기록 조회';const select=el('select',{'aria-label':'학생 선택',onchange:e=>{selected=e.target.value;selectedRun='';dashboard()}});for(const s of data.students){const o=el('option',{value:s.id},`${s.grade}학년 ${s.room}반 ${s.number}번 ${s.nickname}`);o.selected=s.id===selected;select.append(o)}const history=data.events.filter(e=>e.owner===selected);const runs=[...new Set(history.map(e=>e.payload.runId))];if(!runs.includes(selectedRun))selectedRun=runs.at(-1)||'';const runSelect=el('select',{'aria-label':'연습 회차',onchange:e=>{selectedRun=e.target.value;dashboard()}});runs.forEach((id,i)=>{const option=el('option',{value:id},`연습 ${i+1}${i===runs.length-1?' (최근)':''}`);option.selected=id===selectedRun;runSelect.append(option)});const events=history.filter(e=>e.payload.runId===selectedRun);const maxHint=Math.max(0,...events.map(e=>e.payload.hint||0));const completed=events.some(e=>['game.completed','mission.completed','workshop.completed','magnet.completed','crane.completed'].includes(e.kind));const table=el('table',{},el('thead',{},el('tr',{},['수신 시각','학습 과정','제출 내용','도움','판정'].map(t=>el('th',{},t)))),el('tbody',{},events.map(e=>el('tr',{},el('td',{},new Date(e.received*1000).toLocaleTimeString('ko-KR')),el('td',{},eventName(e)),el('td',{},(e.payload.resourceTitle||(e.payload.rows?'전지 한 개: '+({dim:'더 어두움',bright:'더 밝음',equal:'같음'})[e.payload.rows.one]+' / 두 개 직렬: '+({dim:'더 어두움',bright:'더 밝음',equal:'같음'})[e.payload.rows.two]:'')||eventAnswer(e)||e.payload.answer||(e.payload.marked?e.payload.marked.map(k=>({battery:'전지 수',bulb:'전구 규격',background:'주변 밝기'})[k]).join(', '):'')||(e.payload.roles?Object.entries(e.payload.roles).map(([k,v])=>({battery:'전지 수',bulb:'전구 규격',background:'주변 밝기'})[k]+': '+(v==='change'?'바꾸기':'같게 두기')).join(', '):'')||e.payload.card||'모형 실행')+(e.payload.evidence?' / 근거: '+(words[e.payload.evidence]||e.payload.evidence):'')+(e.payload.reason?' / '+e.payload.reason:'')),el('td',{},e.payload.hint?`H${e.payload.hint}`:'없음'),el('td',{},e.teacherReview?reviewStatus(e):(e.kind==='workshop.completed'||e.kind==='magnet.completed')?'모형 과정 완료, 설명은 교사 검토':(e.kind==='entry.submitted'||e.kind==='magnetIntro.recalled')?'도입 진단, 경험 미채점':e.task==='resource'?'열람 행동, 성취 미판정':e.payload.correct===true?'충족 후보':e.payload.correct===false?'다시 확인':'과정 기록')))));
app.replaceChildren(el('div',{class:'worldheading'},el('div',{},el('div',{class:'eyebrow'},'선생님의 배움 관찰실'),el('h1',{},'과정으로 보는 오늘의 탐구')),button('나가기',logout,'secondary')),el('div',{class:'card'},el('label',{},'학생 선택'),select,el('label',{},'연습 회차'),runSelect,el('div',{class:'actions'},button('학습 대시보드',()=>openLearningDashboard({api})),button('관리자 페이지',()=>{location.href='/admin'}),button('공간 배치 편집',()=>placementEditor({el,button,api,toast})),button('공간 자료 관리',()=>resourceEditor({el,button,api,toast})),button('활동 배정과 피드백',()=>openTeaching({api})),button('최신 기록 보기',dashboard),button('이 학생 기록 CSV',()=>exportCSV(events,data.students.find(s=>s.id===selected)),'secondary'))),el('div',{class:'stats'},el('div',{class:'card stat'},el('strong',{},completed?'완료':'진행 중'),'이야기 진행'),el('div',{class:'card stat'},el('strong',{},String(events.length)),'서버에 도착한 과정 기록'),el('div',{class:'card stat'},el('strong',{},maxHint?'H'+maxHint:'없음'),'가장 높은 개념 힌트 단계')),el('section',{class:'card'},el('h2',{},'처음 생각부터 새 상황 확인까지'),events.length?el('div',{class:'tablewrap'},table):el('p',{},'아직 전달된 학습 기록이 없습니다. 학생 계정으로 의뢰를 진행해 보세요.')),el('p',{class:'muted'},'자료 열기, 원본 열기, 재생창 열기는 읽기 완료나 영상 완주를 뜻하지 않습니다. 실제 수행과 설명은 활동 배정과 피드백에서 따로 확인합니다. 예상 정오와 힌트 횟수로 태도를 판정하지 않습니다.'))}catch(e){toast(e.message)}}
